#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader backdrop;
float4 amzSample_comp(float2 uv) { return float4(backdrop.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_comp(uv);return float4(0.0); }
uniform float amzp_mapSrc;
uniform float amzp_mode;
uniform float amzp_channel;
uniform float amzp_amount;
uniform float amzp_angle;
uniform float amzp_centerX;
uniform float amzp_centerY;
uniform float amzp_midpoint;
uniform float amzp_invert;
uniform float amzp_mapBlur;
uniform float amzp_mapScale;
uniform float amzp_mapContrast;
uniform float amzp_noiseSize;
uniform float amzp_noiseDetail;
uniform float amzp_evolution;
uniform float amzp_evoSpeed;
uniform float amzp_steps;
uniform float amzp_dispersion;
uniform float amzp_edges;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float h21(float2 q) { return fract(sin(dot(q, float2(127.1, 311.7))) * 43758.5453); }
    float vn(float2 q) {
        float2 i = floor(q), f = fract(q);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(h21(i), h21(i + float2(1.0, 0.0)), f.x), mix(h21(i + float2(0.0, 1.0)), h21(i + float2(1.0, 1.0)), f.x), f.y);
    }
    float evo;
    float4 noiseMap(float2 px) {
        float2 q = px / max(amzp_noiseSize, 2.0);
        float s = 0.0, a = 0.5, n = 0.0;
        float2 e = float2(cos(evo), sin(evo)) * 1.7;
        for (int i = 0; i < 6; i++) {
            if (float(i) >= amzp_noiseDetail) break;
            s += a * vn(q + e * (1.0 + float(i) * 0.37) + float(i) * 13.1);
            n += a;
            q = float2x2(1.6, 1.2, -1.2, 1.6) * q;
            a *= 0.5;
        }
        float v = s / max(n, 1e-4);
        float g = vn(q * 0.5 + 41.0 - e);
        return float4(v, g, 1.0 - v, 1.0);
    }
    float4 mapRaw(float2 px) {
        float2 W = layer;
        float2 c = W * 0.5;
        float2 q = c + (px - c) / max(amzp_mapScale, 0.01);
        if (int(amzp_mapSrc) == 2) return noiseMap(q);
        float4 m = int(amzp_mapSrc) == 1 ? amzTexture(0, l2s(q / W)) : amzTexture(1, l2s(q / W));
        return float4(m.a > 0.0001 ? m.rgb / m.a : float3(0.0), m.a);
    }
    float4 mapAt(float2 px) {
        float r = max(amzp_mapBlur, 0.0);
        if (r < 0.5) return mapRaw(px);
        float4 s = mapRaw(px) * 2.0;
        float w = 2.0;
        for (int i = 0; i < 12; i++) {
            float a = float(i) * 2.39996;
            float rr = r * sqrt((float(i) + 0.5) / 12.0);
            s += mapRaw(px + float2(cos(a), sin(a)) * rr);
            w += 1.0;
        }
        return s / w;
    }
    float chan(float4 m) {
        float v;
        if (int(amzp_channel) == 1) v = m.r;
        else if (int(amzp_channel) == 2) v = m.g;
        else if (int(amzp_channel) == 3) v = m.b;
        else if (int(amzp_channel) == 4) v = m.a;
        else v = dot(m.rgb, float3(0.299, 0.587, 0.114));
        return v;
    }
    float sgn() { return (amzp_invert>0.5) ? -1.0 : 1.0; }
    float2 field(float2 px) {
        float2 W = layer;
        float k = max(amzp_mapContrast, 0.0) * 2.0 * sgn();
        if (int(amzp_mode) == 2) {
            float4 m = mapAt(px);
            return float2(m.r - amzp_midpoint, -(m.g - amzp_midpoint)) * k * amzp_amount;
        }
        if (int(amzp_mode) == 3) {
            float e = 3.0 + max(amzp_mapBlur, 0.0) * 0.25;
            float gx = chan(mapAt(px + float2(e, 0.0))) - chan(mapAt(px - float2(e, 0.0)));
            float gy = chan(mapAt(px + float2(0.0, e))) - chan(mapAt(px - float2(0.0, e)));
            return -float2(gx, gy) / (2.0 * e) * 50.0 * k * amzp_amount;
        }
        float v = (chan(mapAt(px)) - amzp_midpoint) * k * amzp_amount;
        if (int(amzp_mode) == 1) {
            float2 d = px - float2(amzp_centerX, 1.0 - amzp_centerY) * W;
            float l = length(d);
            return l > 1e-3 ? d / l * v : float2(0.0);
        }
        float an = radians(-amzp_angle);
        return float2(cos(an), sin(an)) * v;
    }
    float4 sampleL(float2 px) {
        float2 W = layer;
        float2 uv = px / W;
        if (int(amzp_edges) == 3) {
            if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return float4(0.0);
        } else if (int(amzp_edges) == 1) {
            uv = fract(uv);
        } else if (int(amzp_edges) == 2) {
            uv = 1.0 - abs(1.0 - mod(uv, 2.0));
        } else {
            uv = clamp(uv, 0.0, 1.0);
        }
        return amzTexture(0, l2s(uv));
    }
    float2 follow(float2 p, float s) {
        float n = clamp(floor(amzp_steps + 0.5), 1.0, 8.0);
        float2 q = p;
        for (int i = 0; i < 8; i++) {
            if (float(i) >= n) break;
            q -= field(q) * s / n;
        }
        return q;
    }
    void nmMain() {
        float2 W = layer;
        float2 p = amzLayerNorm() * W;
        evo = radians(amzp_evolution) + time * amzp_evoSpeed * 6.2831853;
        float disp = clamp(amzp_dispersion, 0.0, 1.0);
        float4 o;
        if (disp > 0.001) {
            float4 r = sampleL(follow(p, 1.0 + disp));
            float4 g = sampleL(follow(p, 1.0));
            float4 b = sampleL(follow(p, 1.0 - disp));
            float a = max(r.a, max(g.a, b.a));
            o = float4(r.r, g.g, b.b, a);
        } else {
            o = sampleL(follow(p, 1.0));
        }
        amzOutput = float4(min(o.rgb, float3(o.a)), o.a);
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
